const { MongoClient } = require('mongodb');
const crypto = require('crypto');
const express = require('express');

const app = express();
app.use(express.json());

// Multi-tenant database driver wrapper
class TenantDBDriver {
  constructor(baseUri) {
    this.baseUri = baseUri;
    this.connections = new Map();
    this.tenantMetadata = new Map();
  }

  async getTenantConnection(tenantId) {
    if (this.connections.has(tenantId)) {
      return this.connections.get(tenantId);
    }
    const dbName = this._resolveTenantDB(tenantId);
    const client = await MongoClient.connect(this.baseUri);
    const db = client.db(dbName);
    this.connections.set(tenantId, db);
    return db;
  }

  _resolveTenantDB(tenantId) {
    // Tenant IDs are validated at registration time
    return `tenant_${tenantId}`;
  }

  // Query builder with tenant isolation
  buildAggregation(tenantConfig, userQuery) {
    const pipeline = [];

    // Stage 1: Tenant isolation filter
    pipeline.push({ $match: { _tenantId: tenantConfig.id } });

    // Stage 2: Apply user's search criteria
    if (userQuery.search) {
      const searchStage = this._buildSearchStage(userQuery.search, tenantConfig);
      pipeline.push(searchStage);
    }

    // Stage 3: Apply field projections based on tenant tier
    if (tenantConfig.tier === 'enterprise') {
      pipeline.push({ $project: this._getEnterpriseProjection(tenantConfig) });
    } else {
      pipeline.push({ $project: { _tenantId: 0, __v: 0 } });
    }

    // Stage 4: Pagination
    if (userQuery.limit) {
      pipeline.push({ $limit: Math.min(parseInt(userQuery.limit), 1000) });
    }

    return pipeline;
  }

  _buildSearchStage(searchParams, tenantConfig) {
    const conditions = {};

    for (const [field, value] of Object.entries(searchParams)) {
      // Validate field is in tenant's allowed schema
      if (!this._isAllowedField(field, tenantConfig)) {
        continue;
      }
      conditions[field] = this._buildFieldMatcher(value, tenantConfig);
    }

    return { $match: conditions };
  }

  _buildFieldMatcher(value, tenantConfig) {
    if (typeof value === 'string') {
      // Enterprise tenants get regex search capability
      if (tenantConfig.tier === 'enterprise' && tenantConfig.features.regexSearch) {
        return { $regex: value, $options: 'i' };
      }
      return value;
    }
    if (typeof value === 'object' && value !== null) {
      return this._processOperatorQuery(value, tenantConfig);
    }
    return value;
  }

  _processOperatorQuery(queryObj, tenantConfig) {
    const allowed = ['$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in'];
    const sanitized = {};

    for (const [op, val] of Object.entries(queryObj)) {
      if (allowed.includes(op)) {
        sanitized[op] = val;
      }
    }
    return sanitized;
  }

  _isAllowedField(field, tenantConfig) {
    const blockedFields = ['_tenantId', '__v', '_id'];
    if (blockedFields.includes(field)) return false;
    if (tenantConfig.allowedFields && tenantConfig.allowedFields.length > 0) {
      return tenantConfig.allowedFields.includes(field);
    }
    return true;
  }

  _getEnterpriseProjection(tenantConfig) {
    const proj = { _tenantId: 0, __v: 0 };
    if (tenantConfig.customProjection) {
      Object.assign(proj, tenantConfig.customProjection);
    }
    return proj;
  }
}

// Tenant configuration store
class TenantRegistry {
  constructor() {
    this.tenants = new Map();
  }

  register(tenantId, config) {
    const validated = {
      id: tenantId,
      tier: ['free', 'pro', 'enterprise'].includes(config.tier) ? config.tier : 'free',
      features: this._resolveFeatures(config.tier, config.features),
      allowedFields: Array.isArray(config.allowedFields) ? config.allowedFields : [],
      customProjection: config.customProjection || null
    };
    this.tenants.set(tenantId, validated);
  }

  _resolveFeatures(tier, requestedFeatures) {
    const tierFeatures = {
      free: { regexSearch: false, aggregation: false },
      pro: { regexSearch: false, aggregation: true },
      enterprise: { regexSearch: true, aggregation: true }
    };
    return tierFeatures[tier] || tierFeatures.free;
  }

  get(tenantId) {
    return this.tenants.get(tenantId);
  }
}

const driver = new TenantDBDriver(process.env.MONGO_URI || 'mongodb://localhost:27017');
const registry = new TenantRegistry();

// Pre-register tenants
registry.register('acme-corp', { tier: 'enterprise', allowedFields: ['name', 'email', 'status', 'department'] });
registry.register('small-biz', { tier: 'free', allowedFields: ['name', 'email'] });

// API endpoint for querying tenant data
app.post('/api/:tenantId/query', async (req, res) => {
  try {
    const { tenantId } = req.params;
    const tenantConfig = registry.get(tenantId);

    if (!tenantConfig) {
      return res.status(404).json({ error: 'Tenant not found' });
    }

    const userQuery = req.body;
    const db = await driver.getTenantConnection(tenantId);
    const collection = db.collection(userQuery.collection || 'documents');

    const pipeline = driver.buildAggregation(tenantConfig, userQuery);
    const results = await collection.aggregate(pipeline).toArray();

    res.json({ results, count: results.length });
  } catch (err) {
    res.status(500).json({ error: 'Query failed' });
  }
});

app.listen(3000);
module.exports = { TenantDBDriver, TenantRegistry, app };
